mapper.insert:
INSERT INTO T_PREDICT_ITEM (
       TRADE_DATE
      ,STOCK_ID
      ,SEQ
      ,BOT_PICK
) VALUES (
       #{tradeDate}
      ,#{stockId}
      ,#{seq}
      ,#{botPick}
)
ON CONFLICT (TRADE_DATE, STOCK_ID) DO NOTHING

INSERT INTO T_PREDICT_VOTE (
       ITEM_ID
      ,USER_ID
      ,PICK
) VALUES (
       #{itemId}
      ,#{userId}
      ,#{pick}
)
ON CONFLICT (ITEM_ID, USER_ID) DO UPDATE
   SET  PICK    = EXCLUDED.PICK
       ,UPD_DAY = NOW()

mapper.select:
SELECT  P.TRADE_DATE
       ,P.CLOSE_PRICE   AS RESULT_CLOSE
  FROM T_STOCK_PRICE P
 WHERE 1=1
   AND P.STOCK_ID   = #{stockId}
   AND P.TRADE_DATE = #{tradeDate}

mapper.update:
UPDATE T_PREDICT_ITEM
   SET  BASE_DATE    = #{baseDate}
       ,BASE_CLOSE   = #{baseClose}
       ,RESULT_CLOSE = #{resultClose}
       ,RESULT       = #{result}
       ,GRADED_DAY   = NOW()
 WHERE 1=1
   AND ID     = #{itemId}
   AND RESULT IS NULL

mapper.select:
SELECT V.USER_ID ,U.NICKNAME ,COUNT(*)::INT AS GRADED ,COUNT(*) FILTER (WHERE V.CORRECT)::INT AS HITS FROM T_PREDICT_VOTE V JOIN T_PREDICT_ITEM I ON I.ID = V.ITEM_ID JOIN T_USER U ON U.ID = V.USER_ID WHERE 1=1 AND V.CORRECT IS NOT NULL AND U.DEL_DAY IS NULL
AND I.TRADE_DATE >= #{fromDate}
GROUP BY V.USER_ID, U.NICKNAME HAVING COUNT(*) >= #{minGraded} ORDER BY HITS DESC, (COUNT(*) FILTER (WHERE V.CORRECT))::NUMERIC / COUNT(*) DESC, V.USER_ID LIMIT #{limit}
